                    c = msg.get("content") if isinstance(msg, dict) else None
                    if isinstance(c, str):
                        text = c
                    elif isinstance(c, list):
                        parts = []
                        for x in c:
                            if isinstance(x, dict):
                                parts.append(x.get("text") or "")
                            else:
                                parts.append(str(x))
                        text = " ".join(parts)
                    text = text.replace("\n", " ")[:200]
